INSERT INTO legal_document_revision (id, document_type, version, title, content, content_sha256, status, current_publication_key, effective_at, created_by, published_by, published_at, created_at, updated_at) VALUES (1,'ACCOUNT_CANCELLATION_NOTICE','1.0','账号注销须知','一、注销条件：所有订单、支付、退款和售后事项均已结束。二、注销后果：注销立即生效且不可恢复；当前微信身份将与原账户解绑，再次登录会创建新账户，原账户权益不能恢复。三、即时清理：昵称、头像、手机号等身份资料，以及收货地址、购物车、收藏、浏览记录和未使用优惠券将被清除或去标识化。四、依法保留：已完成的订单、支付、退款、售后、客服、评价、安全和审计记录，将仅为履行法定义务、处理争议和保障交易安全，在适用期限内保留，期满后删除或匿名化。五、身份确认：勾选“我已阅读并了解”并提交，仅表示您确认已知悉本须知；提交时系统将重新核验微信身份。如仍有进行中的交易或售后，系统不会执行注销。','f1c2011691f8470e31a2aac0fc9c36fd311f0c925262f3ebace01a4cd811e0bc','PUBLISHED','ACCOUNT_CANCELLATION_NOTICE',CURRENT_TIMESTAMP,1,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP);
